<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\{AuthController,DashboardController,FamilyController}; use App\Models\{Family,Beneficiary,Orphan,AidDistribution};
Route::redirect('/','/dashboard'); Route::get('/login',[AuthController::class,'show'])->middleware('guest')->name('login'); Route::post('/login',[AuthController::class,'login'])->middleware('guest'); Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){Route::get('/dashboard',DashboardController::class)->name('dashboard'); Route::get('/families',[FamilyController::class,'index'])->name('families.index'); Route::get('/families/create',[FamilyController::class,'create'])->middleware('role:admin,data_entry'); Route::post('/families',[FamilyController::class,'store'])->middleware('role:admin,data_entry'); Route::get('/families/{family}',[FamilyController::class,'show'])->name('families.show'); Route::get('/families/{family}/edit',[FamilyController::class,'edit'])->middleware('role:admin,data_entry'); Route::put('/families/{family}',[FamilyController::class,'update'])->middleware('role:admin,data_entry'); Route::delete('/families/{family}',[FamilyController::class,'destroy'])->middleware('role:admin'); Route::get('/beneficiaries',fn()=>view('index',['title'=>'Beneficiaries','columns'=>['beneficiary_number','full_name','gender','beneficiary_type'],'items'=>Beneficiary::latest()->paginate(15)])); Route::get('/orphans',fn()=>view('index',['title'=>'Orphans','columns'=>['orphan_number','orphan_status','sponsorship_status'],'items'=>Orphan::latest()->paginate(15)])); Route::get('/aid-distributions',fn()=>view('index',['title'=>'Aid Distributions','columns'=>['distribution_date','aid_type','amount','reference_number'],'items'=>AidDistribution::latest()->paginate(15)]));});
